defmodule Ryker.Repo.Migrations.ChatFactsCanBeKeptEverywhere do
  use Ecto.Migration

  # A fact a person saved in Chat for everywhere was kept for that one chat, since every Chat
  # conversation is its own workspace, so no other chat recalled it (J19, overnight QA of
  # 2026-10-10). Andrew, 2026-10-11: "if we need that do that". Such a fact is kept
  # installation-wide, as a remembered answer is, and still expires like any offered fact.

  @answers_only "(((char_length(ref) >= 1) AND (char_length(ref) <= 256) AND (kind = ANY (ARRAY['alias'::text, 'repository_binding'::text, 'evidence_route'::text, 'entity_relationship'::text])) AND (status = ANY (ARRAY['active'::text, 'superseded'::text, 'deleted'::text, 'expired'::text])) AND ((char_length(workspace_ref) >= 1) AND (char_length(workspace_ref) <= 1024)) AND ((char_length(scope_ref) >= 1) AND (char_length(scope_ref) <= 1024)) AND ((char_length(subject) >= 1) AND (char_length(subject) <= 120)) AND ((octet_length(payload) >= 2) AND (octet_length(payload) <= 32768)) AND (char_length(payload_fingerprint) = 64) AND ((char_length(confirmed_by_actor_ref) >= 1) AND (char_length(confirmed_by_actor_ref) <= 1024)) AND ((char_length(confirmation_ref) >= 1) AND (char_length(confirmation_ref) <= 1024)) AND ((char_length(source_transport) >= 1) AND (char_length(source_transport) <= 1024)) AND ((char_length(source_conversation_ref) >= 1) AND (char_length(source_conversation_ref) <= 1024)) AND ((source_thread_ref IS NULL) OR ((char_length(source_thread_ref) >= 1) AND (char_length(source_thread_ref) <= 1024))) AND ((char_length(source_message_ref) >= 1) AND (char_length(source_message_ref) <= 1024)) AND (recall_count >= 0) AND (((scope_kind = 'global'::text) AND (visibility = 'global'::text) AND (workspace_ref = 'installation'::text) AND (scope_ref ~ '^installation:[a-f0-9]{64}$'::text) AND (expires_at IS NULL) AND (answer_provenance IS NOT NULL)) OR ((scope_kind = ANY (ARRAY['conversation'::text, 'repository'::text, 'workspace'::text])) AND (visibility = ANY (ARRAY['conversation'::text, 'workspace'::text])) AND (expires_at IS NOT NULL) AND (expires_at > confirmed_at) AND (answer_provenance IS NULL) AND (((scope_kind = 'conversation'::text) AND (visibility = 'conversation'::text)) OR (scope_kind = 'repository'::text) OR ((scope_kind = 'workspace'::text) AND (visibility = 'workspace'::text)))))))"
  @offered_too "(((char_length(ref) >= 1) AND (char_length(ref) <= 256) AND (kind = ANY (ARRAY['alias'::text, 'repository_binding'::text, 'evidence_route'::text, 'entity_relationship'::text])) AND (status = ANY (ARRAY['active'::text, 'superseded'::text, 'deleted'::text, 'expired'::text])) AND ((char_length(workspace_ref) >= 1) AND (char_length(workspace_ref) <= 1024)) AND ((char_length(scope_ref) >= 1) AND (char_length(scope_ref) <= 1024)) AND ((char_length(subject) >= 1) AND (char_length(subject) <= 120)) AND ((octet_length(payload) >= 2) AND (octet_length(payload) <= 32768)) AND (char_length(payload_fingerprint) = 64) AND ((char_length(confirmed_by_actor_ref) >= 1) AND (char_length(confirmed_by_actor_ref) <= 1024)) AND ((char_length(confirmation_ref) >= 1) AND (char_length(confirmation_ref) <= 1024)) AND ((char_length(source_transport) >= 1) AND (char_length(source_transport) <= 1024)) AND ((char_length(source_conversation_ref) >= 1) AND (char_length(source_conversation_ref) <= 1024)) AND ((source_thread_ref IS NULL) OR ((char_length(source_thread_ref) >= 1) AND (char_length(source_thread_ref) <= 1024))) AND ((char_length(source_message_ref) >= 1) AND (char_length(source_message_ref) <= 1024)) AND (recall_count >= 0) AND (((scope_kind = 'global'::text) AND (visibility = 'global'::text) AND (workspace_ref = 'installation'::text) AND (scope_ref ~ '^installation:[a-f0-9]{64}$'::text) AND (((expires_at IS NULL) AND (answer_provenance IS NOT NULL)) OR ((expires_at IS NOT NULL) AND (expires_at > confirmed_at) AND (answer_provenance IS NULL)))) OR ((scope_kind = ANY (ARRAY['conversation'::text, 'repository'::text, 'workspace'::text])) AND (visibility = ANY (ARRAY['conversation'::text, 'workspace'::text])) AND (expires_at IS NOT NULL) AND (expires_at > confirmed_at) AND (answer_provenance IS NULL) AND (((scope_kind = 'conversation'::text) AND (visibility = 'conversation'::text)) OR (scope_kind = 'repository'::text) OR ((scope_kind = 'workspace'::text) AND (visibility = 'workspace'::text)))))))"

  def up, do: replace_check(@offered_too)

  # An offered fact kept everywhere breaks the previous rule, so a rollback with one on file
  # refuses rather than dropping a fact a person confirmed.
  def down, do: replace_check(@answers_only)

  defp replace_check(check) do
    drop(constraint(:operational_memory_entries, :operational_memory_entry_valid))

    create(constraint(:operational_memory_entries, :operational_memory_entry_valid, check: check))
  end
end
